import type { EngineInterface, Register } from 'claude-code'

import {
  cleanRemovals,
  CD_SCRIPT,
  describe,
  listed,
  lostChanges,
  MIGRATION_LISTERS,
  parseRm,
  RM_SCRIPT,
  size,
  type Preview,
} from './preview'
import {
  badSubject,
  cleanDryRun,
  commitSubject,
  discardScope,
  droppedStash,
  gitCalls,
  gitRisks,
  PROTECTED_BRANCHES,
  pushTargets,
  shellRisks,
  stripAttribution,
  type GitCall,
  type Risk,
} from './rules'
import { configCommand, LANGUAGE, loadConfig, pick, resolve, type ConfigIO, type Lang, type Resolved, type Specs } from './config'
import { CONFIRM, TONE } from './ui'

const MOD = 'tool-guard'
const ALLOW = 'allow'
const ALLOW_WINDOW_MS = 10 * 60 * 1000
// The rule a command is blocked under when the guard itself failed to check it.
const CHECK_FAILED = 'check-failed'
// What a failed check still blocks; every other command runs as usual.
const GUARDED = /\b(?:git|rm|migrate)\b|db:migrate/

const PANE = 'tool-guard'
// A hook has 10 s of its own time, but time inside a `$` call is free, so the hold waits on a
// short `sleep` process until a button sets the decision.
const POLL_SECONDS = '0.25'
const HOLD_LIMIT_MS = 10 * 60 * 1000
const TIMEOUT_MS = 15_000

type Answer = 'proceed' | 'cancel'

// A command waiting on the person: what it would change and, once pressed, their answer.
type Hold = { command: string; previews: Preview[]; answer?: Answer }

// --- measuring --------------------------------------------------------------------------

async function run($: EngineInterface, argv: string[], cwd?: string) {
  return $.process.run(argv, { ...(cwd ? { cwd } : {}), timeoutMs: TIMEOUT_MS })
}

// The absolute folder a command runs in: undefined for the session's, null when it cannot
// be told (`cd -`, a folder that does not exist).
async function resolveDir($: EngineInterface, dir: string | undefined): Promise<string | undefined | null> {
  if (dir === undefined) {
    return undefined
  }
  if (dir === '-') {
    return null
  }
  const ran = await run($, ['bash', '-c', CD_SCRIPT, 'tool-guard', dir])
  const out = ran.stdout.trim()

  return ran.exitCode === 0 && out !== '' ? out : null
}

async function currentBranch($: EngineInterface, cwd?: string): Promise<string | undefined> {
  const ran = await run($, ['git', 'rev-parse', '--abbrev-ref', 'HEAD'], cwd)

  return ran.exitCode === 0 ? ran.stdout.trim() : undefined
}

// What a force push drops: per target branch, the commits there that the pushed source
// lacks, as of the last fetch. Undefined when it drops none from an unprotected branch.
async function previewPush($: EngineInterface, lang: Lang, risk: Risk & { call: GitCall }, cwd?: string): Promise<Preview | undefined> {
  const dropped: string[] = []
  const notes: string[] = []
  let isProtected = false
  const refs: string[] = []
  for (const target of pushTargets(risk.call.args)) {
    const branch = target.branch ?? (await currentBranch($, cwd))
    if (!branch) {
      notes.push(pick(lang, { en: 'Cannot tell the current branch.', 'zh-TW': '無法判斷目前的分支。' }))
      continue
    }
    isProtected ||= PROTECTED_BRANCHES.includes(branch)
    const ref = `${target.remote}/${branch}`
    refs.push(ref)
    const known = await run($, ['git', 'rev-parse', '--verify', '--quiet', ref], cwd)
    if (known.exitCode !== 0) {
      notes.push(
        pick(lang, {
          en: `There is no ${ref} locally, so the commits it would overwrite cannot be listed; run git fetch first.`,
          'zh-TW': `本機沒有 ${ref}，無法列出會被蓋掉的 commit；先 git fetch 再看。`,
        }),
      )
      continue
    }
    const log = await run($, ['git', 'log', '--oneline', '--no-decorate', `${target.source}..${ref}`], cwd)
    dropped.push(...log.stdout.split('\n').filter(line => line !== ''))
  }
  if (dropped.length === 0 && notes.length === 0 && !isProtected) {
    return undefined
  }
  const where = refs.join(lang === 'zh-TW' ? '、' : ', ') || pick(lang, { en: 'the remote branch', 'zh-TW': '遠端分支' })

  return {
    rule: 'force-push',
    label: risk.label,
    summary:
      dropped.length > 0
        ? pick(lang, { en: `Overwrites ${dropped.length} commit(s) on ${where}`, 'zh-TW': `蓋掉 ${where} 上的 ${dropped.length} 個 commit` })
        : isProtected
          ? pick(lang, { en: `Rewrites the protected ${where}`, 'zh-TW': `改寫受保護的 ${where}` })
          : pick(lang, { en: `Force push to ${where}`, 'zh-TW': `force push 到 ${where}` }),
    ...listed(dropped),
    note: [...notes, pick(lang, { en: 'The list reflects the remote as of the last fetch.', 'zh-TW': '清單依上次 fetch 的遠端狀態。' })].join(' '),
  }
}

async function previewDiscard($: EngineInterface, lang: Lang, risk: Risk & { call: GitCall }, cwd?: string): Promise<Preview | undefined> {
  if (risk.call.sub === 'clean') {
    const ran = await run($, ['git', ...cleanDryRun(risk.call.args)], cwd)
    if (ran.exitCode !== 0) {
      return {
        rule: 'discard',
        label: risk.label,
        summary: pick(lang, { en: 'Cannot dry-run git clean -n', 'zh-TW': '無法試跑 git clean -n' }),
        lines: [],
        more: 0,
        note: ran.stderr.trim().slice(0, 200),
      }
    }
    const removed = cleanRemovals(ran.stdout)

    return removed.length === 0
      ? undefined
      : {
          rule: 'discard',
          label: risk.label,
          summary: pick(lang, { en: `Deletes ${removed.length} untracked path(s)`, 'zh-TW': `刪除 ${removed.length} 個未追蹤的路徑` }),
          ...listed(removed),
          note: pick(lang, {
            en: 'The list comes from git clean -n; untracked files are not in git, so deleting them cannot be undone.',
            'zh-TW': '清單來自 git clean -n；未追蹤的檔案不在 git 裡，刪了無法復原。',
          }),
        }
  }

  const scope = discardScope(risk.call)
  const status = await run($, ['git', 'status', '--porcelain', '--', ...scope.paths], cwd)
  if (status.exitCode !== 0) {
    return {
      rule: 'discard',
      label: risk.label,
      summary: pick(lang, { en: 'Cannot read git status', 'zh-TW': '無法讀取 git status' }),
      lines: [],
      more: 0,
      note: status.stderr.trim().slice(0, 200),
    }
  }
  const lost = lostChanges(status.stdout, scope.isStagedLost)
  if (lost.length === 0) {
    return undefined
  }
  const stat = await run($, ['git', 'diff', '--shortstat', ...(scope.isStagedLost ? ['HEAD'] : []), '--', ...scope.paths], cwd)

  return {
    rule: 'discard',
    label: risk.label,
    summary: pick(lang, { en: `Discards uncommitted changes in ${lost.length} file(s)`, 'zh-TW': `丟掉 ${lost.length} 個檔案未 commit 的改動` }),
    ...listed(lost),
    note: [
      stat.stdout.trim(),
      pick(lang, { en: 'Uncommitted changes cannot be recovered; save them with git stash or a commit first.', 'zh-TW': '未 commit 的改動無法復原，先用 git stash 或 commit 保存。' }),
    ]
      .filter(part => part !== '')
      .join(pick(lang, { en: '. ', 'zh-TW': '。' })),
  }
}

async function previewStash($: EngineInterface, lang: Lang, risk: Risk & { call: GitCall }, cwd?: string): Promise<Preview | undefined> {
  const list = await run($, ['git', 'stash', 'list'], cwd)
  const stashes = list.stdout.split('\n').filter(line => line !== '')
  if (stashes.length === 0) {
    return undefined
  }
  const ref = droppedStash(risk.call)
  if (ref === undefined) {
    return {
      rule: 'stash-drop',
      label: risk.label,
      summary: pick(lang, { en: `Permanently deletes all ${stashes.length} stash(es)`, 'zh-TW': `永久刪除全部 ${stashes.length} 個 stash` }),
      ...listed(stashes),
    }
  }
  const show = await run($, ['git', 'stash', 'show', '--stat', ref], cwd)
  const entry = stashes.find(line => line.startsWith(`${ref}:`))

  return {
    rule: 'stash-drop',
    label: risk.label,
    summary: pick(lang, { en: `Permanently deletes ${entry ?? ref}`, 'zh-TW': `永久刪除 ${entry ?? ref}` }),
    ...listed(show.stdout.split('\n').filter(line => line.trim() !== '')),
  }
}

async function previewRm(
  $: EngineInterface,
  lang: Lang,
  risk: Risk & { rule: 'rm' },
  skips: readonly string[],
  cwd?: string,
): Promise<Preview | undefined> {
  if (risk.targets.length === 0) {
    return undefined
  }
  const ran = await run($, ['bash', '-c', RM_SCRIPT, 'tool-guard', skips.join('\n'), ...risk.targets], cwd)
  if (ran.exitCode !== 0) {
    return {
      rule: 'rm',
      label: risk.label,
      summary: pick(lang, { en: 'Cannot estimate the files to be deleted', 'zh-TW': '無法估算會刪除的檔案' }),
      lines: [],
      more: 0,
      note: ran.stderr.trim().slice(0, 200),
    }
  }
  const measured = parseRm(ran.stdout)
  // Nothing matches, everything is under a temp folder, or only empty folders go.
  if (measured.paths === 0 || measured.files === 0) {
    return undefined
  }

  return {
    rule: 'rm',
    label: risk.label,
    summary: pick(lang, {
      en: `Deletes ${measured.files} file(s) (about ${size(measured.bytes)})`,
      'zh-TW': `刪除 ${measured.files} 個檔案（約 ${size(measured.bytes)}）`,
    }),
    lines: measured.listed,
    more: Math.max(0, measured.files - measured.listed.length),
    note: pick(lang, { en: `Paths: ${risk.targets.join(' ')}`, 'zh-TW': `路徑：${risk.targets.join(' ')}` }),
  }
}

async function previewMigrate($: EngineInterface, lang: Lang, risk: Risk & { rule: 'migrate' }, cwd?: string): Promise<Preview | undefined> {
  const lister = MIGRATION_LISTERS[risk.tool]
  if (lister === undefined) {
    return {
      rule: 'migrate',
      label: risk.label,
      summary: pick(lang, { en: 'Runs a migration', 'zh-TW': '執行 migration' }),
      lines: [],
      more: 0,
      note: pick(lang, { en: 'The pending migrations of this tool cannot be listed.', 'zh-TW': '無法列出這個工具待執行的 migration。' }),
    }
  }
  const ran = await run($, lister.argv, cwd)
  if (ran.exitCode !== 0) {
    return {
      rule: 'migrate',
      label: risk.label,
      summary: pick(lang, { en: 'Runs a migration', 'zh-TW': '執行 migration' }),
      lines: [],
      more: 0,
      note: pick(lang, {
        en: `Cannot list the pending migrations (${lister.argv.join(' ')} failed).`,
        'zh-TW': `無法列出待執行的 migration（${lister.argv.join(' ')} 失敗）。`,
      }),
    }
  }
  const pending = ran.stdout.split('\n').filter(lister.isPending).map(lister.strip)

  return pending.length === 0
    ? undefined
    : {
        rule: 'migrate',
        label: risk.label,
        summary: pick(lang, { en: `Applies ${pending.length} pending migration(s)`, 'zh-TW': `套用 ${pending.length} 個待執行的 migration` }),
        ...listed(pending),
        note: pick(lang, { en: `The list comes from ${lister.argv.join(' ')}.`, 'zh-TW': `清單來自 ${lister.argv.join(' ')}。` }),
      }
}

// What the risk would change, or undefined when it would change nothing worth asking about.
// A measurement that fails is shown as such and still asks.
async function previewOf($: EngineInterface, lang: Lang, risk: Risk, skips: readonly string[]): Promise<Preview | undefined> {
  const where = 'call' in risk ? risk.call.dir : risk.dir
  const cwd = await resolveDir($, where)
  if (cwd === null) {
    return {
      rule: risk.rule,
      label: risk.label,
      summary: pick(lang, { en: `Cannot estimate (directory ${where} not found)`, 'zh-TW': `無法估算（找不到目錄 ${where}）` }),
      lines: [],
      more: 0,
    }
  }
  try {
    switch (risk.rule) {
      case 'force-push':
        return await previewPush($, lang, risk, cwd)
      case 'discard':
        return await previewDiscard($, lang, risk, cwd)
      case 'stash-drop':
        return await previewStash($, lang, risk, cwd)
      case 'no-verify':
        return {
          rule: risk.rule,
          label: risk.label,
          summary: pick(lang, {
            en: 'Skips the checks of git hooks (pre-commit, commit-msg, pre-push)',
            'zh-TW': '略過 git hooks（pre-commit、commit-msg、pre-push）的檢查',
          }),
          lines: [],
          more: 0,
        }
      case 'rm':
        return await previewRm($, lang, risk, skips, cwd)
      case 'migrate':
        return await previewMigrate($, lang, risk, cwd)
    }
  } catch (error) {
    return {
      rule: risk.rule,
      label: risk.label,
      summary: pick(lang, { en: 'Cannot estimate the impact', 'zh-TW': '無法估算影響範圍' }),
      lines: [],
      more: 0,
      note: String(error).slice(0, 200),
    }
  }
}

// --- holding ----------------------------------------------------------------------------

// Waits for the person's answer to `hold`; the pane is already up.
async function waitForAnswer($: EngineInterface, hold: Hold, signal: AbortSignal): Promise<Answer | 'timeout' | 'interrupted'> {
  const startedAt = await $.clock.now()
  while (hold.answer === undefined) {
    if (signal.aborted) {
      return 'interrupted'
    }
    if ((await $.clock.now()) - startedAt > HOLD_LIMIT_MS) {
      return 'timeout'
    }
    await $.process.run(['sleep', POLL_SECONDS], { timeoutMs: 5000 })
  }

  return hold.answer
}

type Asked = { answer: Answer | 'dismissed'; reply?: string }

// Asks in the engine's own question dialog, which fits any width: the fallback for a pane the
// surface will not place. Cancel comes first, so a dialog that settles by default refuses.
async function askAnswer($: EngineInterface, lang: Lang, previews: Preview[]): Promise<Asked> {
  const cancel = pick(lang, { en: 'Cancel', 'zh-TW': '取消' })
  const run = pick(lang, { en: 'Run', 'zh-TW': '執行' })
  let choice: string
  try {
    choice = await $.ui.ask(`${describe(previews, lang)}\n\n${pick(lang, { en: 'Run this command?', 'zh-TW': '要執行這個指令嗎？' })}`, {
      options: [cancel, run],
      header: 'tool-guard',
    })
  } catch {
    return { answer: 'dismissed' }
  }
  if (choice === run) {
    return { answer: 'proceed' }
  }

  return choice === cancel || choice === '' ? { answer: 'cancel' } : { answer: 'cancel', reply: choice }
}

function paneRows(previews: Preview[]): number {
  const body = previews.reduce((sum, p) => sum + 1 + p.lines.length + (p.more > 0 ? 1 : 0) + (p.note ? 1 : 0), 0)

  return Math.min(24, 6 + body)
}

export const SPECS: Specs = {
  commit_format: {
    category: 'protect',
    type: 'boolean',
    default: false,
    repo: 'only-true',
    description: {
      en: 'Check the commit subject format; a subject that does not match is blocked and Claude is asked to fix it',
      'zh-TW': '檢查 commit 標題格式，不符合就擋下請 Claude 改',
    },
  },
  commit_pattern: {
    category: 'plain',
    type: 'string',
    default: '',
    repo: 'any',
    description: {
      en: 'Regular expression a commit subject must match; empty means `<emoji> type(scope)!: description` (Conventional Commits)',
      'zh-TW': 'commit 標題要符合的正規表示式；空白時用 `<emoji> type(scope)!: 描述`（Conventional Commits）',
    },
  },
  strip_attribution: {
    category: 'plain',
    type: 'boolean',
    default: true,
    repo: 'any',
    description: { en: "Remove Claude's Co-Authored-By trailer from commit messages", 'zh-TW': '從 commit 訊息移除 Claude 的 Co-Authored-By 署名' },
  },
  rm_skip_paths: {
    category: 'protect',
    type: 'list',
    default: [],
    repo: 'never',
    description: {
      en: 'Folders rm is not checked in (besides temp folders); only in the user settings file or the local file',
      'zh-TW': 'rm 不檢查的資料夾（暫存資料夾之外再加的）；只能放在使用者設定檔或 local 檔案',
    },
  },
  language: LANGUAGE,
}

// --- configIO: the same block in every mod (scripts/check-copies.sh) ---
function configIO($: EngineInterface): ConfigIO {
  return {
    read: async path => {
      try {
        return await $.fs.read(path)
      } catch {
        return ''
      }
    },
    write: (path, text) => $.fs.write(path, text),
    isDir: async path => (await $.fs.stat(path).catch(() => undefined))?.kind === 'dir',
    configDir: async () => (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${(await $.env.get('HOME')) ?? ''}/.claude`,
    root: () => $.session.root(),
    repoRoot: async () => (await $.session.repo())?.root,
    sessionId: () => $.session.id(),
    now: () => $.clock.now(),
    storeGet: key => $.store.get(key),
    storeSet: (key, value) => $.store.set(key, value),
  }
}
// --- end configIO ---

// The setting `commit_pattern` as a RegExp; undefined for the built-in format or a pattern that does not compile.
export function subjectPattern(pattern: string): RegExp | undefined {
  if (pattern.trim() === '') {
    return undefined
  }
  try {
    return new RegExp(pattern)
  } catch {
    return undefined
  }
}

export const register: Register = (on, options) => {
  // Re-read at session start and after `/tool-guard set`; `/config` changes reload the module.
  let config: Resolved = resolve(SPECS, { options, user: {}, repo: {}, local: {}, session: {} })
  const apply = (resolved: Resolved) => {
    config = resolved
  }
  // One allowance the person grants with /tool-guard allow, for the rules last blocked.
  let lastBlocked: string[] | undefined
  let allowance: { rules: string[]; until: number } | undefined
  let isInteractive = true
  // The command the pane shows. One at a time: a second risky call waits for the first.
  let held: Hold | undefined

  // Spends the allowance when it covers every rule and has not expired.
  function takeAllowance(rules: string[], now: number): boolean {
    if (!allowance || now > allowance.until || !rules.every(rule => allowance?.rules.includes(rule))) {
      return false
    }
    allowance = undefined

    return true
  }

  function denial(rules: string[], reason: string): { deny: string } {
    lastBlocked = rules

    return {
      deny:
        `tool-guard: ${reason}\n` +
        pick(config.lang, {
          en: `If you are sure it should run, first explain why to the user and ask them to type /${MOD} ${ALLOW}, then run the same command again.`,
          'zh-TW': `若確定要執行，請先向使用者說明原因並請他輸入 /${MOD} ${ALLOW}，再重新執行同一個指令。`,
        }),
    }
  }

  on('session.start', async ($, e, next) => {
    isInteractive = e.isInteractive
    try {
      apply(await loadConfig(configIO($), MOD, SPECS, options))
    } catch (error) {
      $.ui.log(`session.start: settings not read: ${String(error)}`, { to: 'debug' })
    }
    const lang = config.lang
    try {
      await $.command.register({
        name: MOD,
        description: pick(lang, {
          en: 'Allow the next command of the same kind that tool-guard blocked (allow, valid for 10 minutes), or view and change settings',
          'zh-TW': '允許下一個被 tool-guard 擋下的同類指令（allow，10 分鐘內有效），或看、改設定',
        }),
        argumentHint: 'allow | status | set <key> <value> | unset <key>',
      })
    } catch (error) {
      $.ui.log(`session.start: /${MOD} not registered: ${String(error)}`, { to: 'debug' })
      $.ui.toast(pick(lang, { en: `${MOD}: /${MOD} was not registered (${String(error)})`, 'zh-TW': `${MOD}：/${MOD} 指令沒有註冊成功（${String(error)}）` }))
    }
    if (config.values.commit_pattern !== '' && subjectPattern(config.values.commit_pattern as string) === undefined) {
      $.ui.toast(
        pick(lang, {
          en: `${MOD}: commit_pattern is not a valid regular expression; the built-in format is used`,
          'zh-TW': `${MOD}：commit_pattern 不是有效的正規表示式，改用內建格式`,
        }),
      )
    }

    return next(e)
  })

  on('command.run', { command: MOD }, async ($, e) => {
    if (e.args.trim().split(/\s+/)[0] !== ALLOW) {
      const text = await configCommand(configIO($), MOD, SPECS, options, e.args, apply)

      const usage = pick(config.lang, {
        en: `Usage: /${MOD} ${ALLOW}, /${MOD} status, /${MOD} set <key> <value> [--session|--local|--repo], /${MOD} unset <key>`,
        'zh-TW': `用法：/${MOD} ${ALLOW}、/${MOD} status、/${MOD} set <key> <value> [--session|--local|--repo]、/${MOD} unset <key>`,
      })

      return { text: text ?? usage }
    }
    if (lastBlocked === undefined) {
      return { text: pick(config.lang, { en: 'tool-guard has not blocked any command yet.', 'zh-TW': 'tool-guard 目前沒有擋下任何指令。' }) }
    }
    allowance = { rules: lastBlocked, until: (await $.clock.now()) + ALLOW_WINDOW_MS }
    const names = lastBlocked.join(config.lang === 'zh-TW' ? '、' : ', ')

    return {
      text: pick(config.lang, {
        en: `The user allowed the next command that tool-guard blocks under the rule(s) "${names}" (valid for 10 minutes); you can run it again.`,
        'zh-TW': `使用者已允許下一個被 tool-guard 以「${names}」規則擋下的指令（10 分鐘內有效），可以重新執行。`,
      }),
    }
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const calls = gitCalls(e.command)
    const risks = [...calls.flatMap(gitRisks), ...shellRisks(e.command)]
    if (calls.length === 0 && risks.length === 0) {
      return next(e)
    }

    // A malformed commit subject is Claude's to fix, not the person's to approve.
    const lang = config.lang
    const pattern = subjectPattern(config.values.commit_pattern as string)
    for (const call of config.values.commit_format === true ? calls : []) {
      const subject = call.sub === 'commit' ? commitSubject(e.command, call.args) : undefined
      if (subject !== undefined && badSubject(subject, pattern) && !takeAllowance(['subject'], await $.clock.now())) {
        $.ui.toast(pick(lang, { en: 'tool-guard: blocked commit subject format', 'zh-TW': 'tool-guard：擋下 commit 標題格式' }))

        return denial(
          ['subject'],
          pattern === undefined
            ? pick(lang, {
                en:
                  `The commit subject "${subject}" does not follow Conventional Commits. ` +
                  'Format: `<emoji> <type>(<scope>): <description>`; emoji and scope are optional, e.g. `✨ feat(claude): add tool-guard`.',
                'zh-TW':
                  `commit 標題「${subject}」不符合 Conventional Commits。` +
                  '格式：`<emoji> <type>(<scope>): <描述>`，emoji 與 scope 可省略，例如 `✨ feat(claude): 新增 tool-guard`。',
              })
            : pick(lang, {
                en: `The commit subject "${subject}" does not match the format set for this repo: \`${pattern.source}\`.`,
                'zh-TW': `commit 標題「${subject}」不符合這個 repo 設定的格式 \`${pattern.source}\`。`,
              }),
        )
      }
    }

    const previews: Preview[] = []
    for (const risk of risks) {
      const preview = await previewOf($, lang, risk, config.values.rm_skip_paths as readonly string[])
      if (preview) {
        previews.push(preview)
      }
    }
    const rules = [...new Set(previews.map(preview => preview.rule))]

    if (previews.length > 0 && takeAllowance(rules, await $.clock.now())) {
      $.ui.toast(
        pick(lang, {
          en: `tool-guard: let through as the user allowed (${rules.join(', ')})`,
          'zh-TW': `tool-guard：依使用者允許放行（${rules.join('、')}）`,
        }),
      )
    } else if (previews.length > 0) {
      // One hold at a time; `held` is claimed with no await between the check and the claim.
      while (held !== undefined) {
        if (next.signal.aborted) {
          return {
            deny: pick(lang, {
              en: 'tool-guard: the turn was interrupted and the command did not run. Do not retry unless the user asks.',
              'zh-TW': 'tool-guard: 回合已中斷，指令沒有執行。除非使用者要求，不要重試。',
            }),
          }
        }
        await $.process.run(['sleep', POLL_SECONDS], { timeoutMs: 5000 })
      }
      const hold: Hold = { command: e.command, previews }
      held = hold
      $.ui.invalidate('ui.render')
      let answer: Asked['answer'] | 'timeout' | 'interrupted' | 'unplaced' = 'unplaced'
      let reply: string | undefined
      try {
        if (isInteractive) {
          const opened = await $.ui.open({ id: PANE, title: pick(lang, { en: 'tool-guard confirm', 'zh-TW': 'tool-guard 確認' }), focus: true, rows: paneRows(previews) })
          if (opened.isPlaced) {
            answer = await waitForAnswer($, hold, next.signal)
          } else {
            $.ui.log(`tool-guard: pane not placed (${opened.reason}), asking in a dialog instead`, { to: 'debug' })
            await $.ui.close({ id: PANE }).catch(() => undefined)
            ;({ answer, reply } = await askAnswer($, lang, previews))
          }
        }
      } finally {
        // Close this call's pane before releasing the hold, so the next call's pane is not
        // the one closed. An unplaced pane is closed too, so it never shows up later.
        await $.ui.close({ id: PANE }).catch(() => undefined)
        if (held === hold) {
          held = undefined
        }
        $.ui.invalidate('ui.render')
      }

      const what = describe(previews, lang)
      if (answer === 'unplaced') {
        $.ui.toast(pick(lang, { en: `tool-guard: blocked ${rules.join(', ')}`, 'zh-TW': `tool-guard：擋下 ${rules.join('、')}` }))

        return denial(
          rules,
          pick(lang, {
            en: `This command would have the following effects; it is blocked because this is a non-interactive session and the user cannot be asked:\n${what}`,
            'zh-TW': `這個指令會造成以下影響，因為是非互動模式、無法詢問使用者，所以先擋下：\n${what}`,
          }),
        )
      }
      if (answer !== 'proceed') {
        const why = {
          cancel: reply
            ? pick(lang, { en: `The user did not choose to run it and replied: "${reply}"`, 'zh-TW': `使用者沒有選擇執行，回覆：「${reply}」` })
            : pick(lang, { en: 'The user pressed Cancel', 'zh-TW': '使用者按了取消' }),
          timeout: pick(lang, { en: 'No answer within 10 minutes', 'zh-TW': '10 分鐘內沒有回應' }),
          interrupted: pick(lang, { en: 'The turn was interrupted', 'zh-TW': '回合已中斷' }),
          dismissed: pick(lang, { en: 'The user closed the question dialog', 'zh-TW': '使用者關閉了詢問對話框' }),
        }[answer]

        return {
          deny: pick(lang, {
            en: `tool-guard: ${why}, so the command did not run. It would have:\n${what}\nDo not retry unless the user asks.`,
            'zh-TW': `tool-guard: ${why}，指令沒有執行。它原本會：\n${what}\n除非使用者要求，不要重試。`,
          }),
        }
      }
      $.ui.toast(pick(lang, { en: 'tool-guard: confirmed by the user, running the command', 'zh-TW': 'tool-guard：使用者確認，執行指令' }))
    }

    const stripped = stripAttribution(e.command)
    if (config.values.strip_attribution === true && stripped.isChanged && calls.some(call => call.sub === 'commit')) {
      $.ui.toast(pick(lang, { en: 'tool-guard: removed the Claude trailer from the commit message', 'zh-TW': 'tool-guard：已從 commit 訊息移除 Claude 署名' }))

      return next({ ...e, command: stripped.command })
    }

    return next(e)
  }).catch(async ($, e, next) => {
    // A broken guard must not let a destructive command run unchecked: guarded commands wait
    // for /tool-guard allow, every other command runs as usual.
    if (next.called || !GUARDED.test(e.command)) {
      return next(e)
    }
    const lang = config.lang
    // A Bash call raised beneath one of this hook's own `$` calls: `$` rejects here, so it is
    // judged from `e` alone.
    if (next.error.kind === 're-entry') {
      return {
        deny: pick(lang, {
          en: 'tool-guard: this command was triggered while a check was running and cannot be checked, so it is blocked.',
          'zh-TW': 'tool-guard: 這個指令在檢查進行中被觸發，無法檢查，已擋下。',
        }),
      }
    }
    if (takeAllowance([CHECK_FAILED], await $.clock.now().catch(() => Infinity))) {
      $.ui.toast(pick(lang, { en: 'tool-guard: the check failed; let through as the user allowed', 'zh-TW': 'tool-guard：檢查失敗，依使用者允許放行' }))

      return next(e)
    }
    $.ui.toast(pick(lang, { en: 'tool-guard: the check failed; the command is blocked', 'zh-TW': 'tool-guard：檢查失敗，已擋下指令' }))

    return denial(
      [CHECK_FAILED],
      pick(lang, {
        en: `The check failed (${next.error.message ?? next.error.kind}); a command that has not been checked is always blocked.`,
        'zh-TW': `檢查失敗（${next.error.message ?? next.error.kind}），未經檢查的指令一律擋下。`,
      }),
    )
  })

  // A pane the person closes by hand is a Cancel.
  on('ui.close', async ($, e, next) => {
    if (e.id === PANE && e.origin.kind === 'person' && held && held.answer === undefined) {
      held.answer = 'cancel'
    }

    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, ($, e, next) => {
    const hold = held
    if (!hold) {
      return next(e)
    }
    const { Box, Button, Text } = $.ui.resolve(e)
    const lang = config.lang
    // The buttons answer the command this pane was drawn for, never whichever is held now.
    const answer = (choice: Answer) => () => {
      hold.answer ??= choice
    }

    return (
      <Box flexDirection="column" {...CONFIRM}>
        <Text wrap="truncate-end">
          <Text dimColor>{pick(lang, { en: 'Command ', 'zh-TW': '指令 ' })}</Text>
          <Text bold>{hold.command.replace(/\s+/g, ' ')}</Text>
        </Text>
        {hold.previews.map((preview, i) => (
          <Box key={`p${i}`} flexDirection="column" marginTop={1}>
            <Text>
              <Text bold>{preview.label}</Text>
              <Text>  </Text>
              <Text bold color={TONE.danger}>
                {preview.summary}
              </Text>
            </Text>
            {preview.lines.map((line, j) => (
              <Text key={`l${j}`} wrap="truncate-end">
                {`  ${line}`}
              </Text>
            ))}
            {preview.more > 0 && <Text dimColor>{`  ${pick(lang, { en: `${preview.more} more`, 'zh-TW': `另有 ${preview.more} 項` })}`}</Text>}
            {preview.note && (
              <Text dimColor wrap="wrap">
                {preview.note}
              </Text>
            )}
          </Box>
        ))}
        <Box marginTop={1} gap={2}>
          <Button key="proceed" label={pick(lang, { en: 'Run', 'zh-TW': '執行' })} hotkey="1" plain onPress={answer('proceed')} />
          <Button key="cancel" label={pick(lang, { en: 'Cancel', 'zh-TW': '取消' })} hotkey="2" plain autoFocus onPress={answer('cancel')} />
          <Text dimColor>{pick(lang, { en: 'Claude is waiting for your answer', 'zh-TW': 'Claude 等待你回答' })}</Text>
        </Box>
      </Box>
    )
  })
}

files.hooks/preview.ts:
// What a held command would change, as the pane and the denial show it. register.tsx runs
// the commands; this file holds their scripts and turns their output into a Preview.

import { pick, type Lang } from './config'
import type { MigrationTool, Rule } from './rules'

export const LIST_MAX = 10

export type Preview = {
  rule: Rule
  // The operation: `git reset --hard`, `rm -rf`.
  label: string
  // What it would do, in one line.
  summary: string
  lines: string[]
  // Items beyond `lines`.
  more: number
  note?: string
}

export function listed(items: string[]): { lines: string[]; more: number } {
  return { lines: items.slice(0, LIST_MAX), more: Math.max(0, items.length - LIST_MAX) }
}

// `git status --porcelain` rows a discard overwrites, as `XY path`. Untracked files are never
// touched; without staged loss only rows with an unstaged change (Y) count.
export function lostChanges(porcelain: string, isStagedLost: boolean): string[] {
  return porcelain
    .split('\n')
    .filter(row => row.length > 3 && !row.startsWith('??') && !row.startsWith('!!'))
    .filter(row => isStagedLost || row[1] !== ' ')
}

export function cleanRemovals(stdout: string): string[] {
  return stdout
    .split('\n')
    .filter(line => line.startsWith('Would remove '))
    .map(line => line.slice('Would remove '.length))
}

// Expands rm's targets the way the shell would and measures them, skipping paths under the
// temp folders and under the folders in $1 (one per line, the setting `rm_skip_paths`). The
// paths arrive as arguments, never as source, so nothing in them runs;
// compgen -G expands a glob without command substitution. Prints `files bytes paths`, then
// up to LIST_MAX of the files.
export const RM_SCRIPT = [
  'shopt -s nullglob dotglob',
  'tmp=$(cd "${TMPDIR:-/tmp}" 2>/dev/null && pwd -P)',
  'skips=()',
  'while IFS= read -r s; do',
  '  [[ -z "$s" ]] && continue',
  '  case "$s" in "~"|"~/"*) s="$HOME${s#\\~}";; esac',
  '  skips+=("$(cd "$s" 2>/dev/null && pwd -P || printf %s "${s%/}")")',
  'done <<< "$1"',
  'shift',
  'paths=()',
  'add() {',
  '  local abs',
  '  abs="$(cd "$(dirname -- "$1")" 2>/dev/null && pwd -P)/$(basename -- "$1")"',
  '  case "$abs" in /tmp/*|/private/tmp/*|/var/folders/*|/private/var/folders/*) return;; esac',
  '  [[ -n "$tmp" && "$abs" == "$tmp"/* ]] && return',
  '  for s in "${skips[@]}"; do [[ "$abs" == "$s" || "$abs" == "$s"/* ]] && return; done',
  '  case "$seen" in *"|$abs|"*) return;; esac', // a path two targets match counts once
  '  seen="$seen|$abs|"',
  '  paths+=("$1")',
  '}',
  'for p in "$@"; do',
  '  case "$p" in "~"|"~/"*) p="$HOME${p#\\~}";; esac',
  '  if [[ "$p" == *[*?[]* ]]; then',
  '    while IFS= read -r m; do add "$m"; done < <(compgen -G "$p")',
  '  elif [[ -e "$p" || -L "$p" ]]; then',
  '    add "$p"',
  '  fi',
  'done',
  'if (( ${#paths[@]} == 0 )); then echo "0 0 0"; exit 0; fi',
  '# A relative path gets ./ in front, so find never reads a name like -delete as an action.',
  'for i in "${!paths[@]}"; do case "${paths[$i]}" in /*) ;; *) paths[$i]="./${paths[$i]}";; esac; done',
  'files=$(find "${paths[@]}" \\( -type f -o -type l \\) 2>/dev/null | wc -l | tr -d " ")',
  'kb=$(du -skc "${paths[@]}" 2>/dev/null | tail -n1 | cut -f1)',
  'echo "$files $(( ${kb:-0} * 1024 )) ${#paths[@]}"',
  `find "\${paths[@]}" \\( -type f -o -type l \\) 2>/dev/null | head -n ${LIST_MAX}`,
].join('\n')

export type RmMeasure = { files: number; bytes: number; paths: number; listed: string[] }

export function parseRm(stdout: string): RmMeasure {
  const [head, ...rest] = stdout.split('\n').filter(line => line !== '')
  const [files = 0, bytes = 0, paths = 0] = (head ?? '0 0 0').split(' ').map(Number)

  return { files, bytes, paths, listed: rest.map(line => line.replace(/^\.\//, '')) }
}

// Resolves a `cd` target to an absolute folder; prints nothing when it does not exist.
export const CD_SCRIPT =
  'unset CDPATH; d="$1"; case "$d" in "~") d="$HOME";; "~/"*) d="$HOME/${d#\\~/}";; esac; cd -- "$d" 2>/dev/null && pwd -P'

type Lister = { argv: string[]; isPending: (line: string) => boolean; strip: (line: string) => string }

// Each tool's own status command, and how to read the pending migrations off it.
export const MIGRATION_LISTERS: Partial<Record<MigrationTool, Lister>> = {
  django: {
    argv: ['python3', 'manage.py', 'showmigrations', '--plan'],
    isPending: line => line.startsWith('[ ]'),
    strip: line => line.slice(4),
  },
  alembic: { argv: ['alembic', 'history', '-r', 'current:head'], isPending: line => line.includes('->'), strip: line => line },
  rails: { argv: ['bin/rails', 'db:migrate:status'], isPending: line => /^\s*down\b/.test(line), strip: line => line.trim() },
  prisma: {
    argv: ['npx', '--no-install', 'prisma', 'migrate', 'status'],
    isPending: line => /^\s{2}\S/.test(line),
    strip: line => line.trim(),
  },
}

export function size(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes < 1024) {
    return `${bytes || 0} B`
  }
  const units = ['KB', 'MB', 'GB', 'TB']
  let n = bytes
  let i = -1
  while (n >= 1024 && i < units.length - 1) {
    n /= 1024
    i += 1
  }

  return `${n.toFixed(n < 10 ? 1 : 0)} ${units[i]}`
}

// The previews as plain text, for a denial the model relays to the person.
export function describe(previews: Preview[], lang: Lang = 'en'): string {
  return previews
    .map(preview =>
      [
        `${preview.label}${lang === 'zh-TW' ? '：' : ': '}${preview.summary}`,
        ...preview.lines.map(line => `  - ${line}`),
        ...(preview.more > 0 ? [`  - ${pick(lang, { en: `${preview.more} more`, 'zh-TW': `另有 ${preview.more} 項` })}`] : []),
        ...(preview.note ? [`  ${preview.note}`] : []),
      ].join('\n'),
    )
    .join('\n')
}

files.hooks/rules.ts:
// Pure checks over a Bash command line: which operations in it can lose work, and what about
// them is risky. register.tsx measures what each one would actually change before asking.

export type GitCall = {
  sub: string
  args: string
  // The directory `git -C` or a leading `cd <dir> &&` points at, when the command names one.
  dir?: string
}

const GIT_CALL =
  /(?:^|[;&|(\n`]|\$\()\s*(?:[A-Z_][A-Z0-9_]*=\S*\s+)*git((?:\s+-[Cc]\s+(?:"[^"]*"|'[^']*'|\S+)|\s+--[a-z-]+(?:=\S+)?)*)\s+([a-z][a-z-]*)([^;&|\n]*)/g

const LEADING_CD = /^\s*cd\s+("[^"]*"|'[^']*'|[^\s;&|]+)\s*&&/

function unquote(text: string): string {
  return text.replace(/^["']|["']$/g, '')
}

export function gitCalls(command: string): GitCall[] {
  const cd = LEADING_CD.exec(command)?.[1]
  const calls: GitCall[] = []
  for (const match of command.matchAll(GIT_CALL)) {
    const globals = match[1] ?? ''
    const dashC = /-C\s+("[^"]*"|'[^']*'|\S+)/.exec(globals)?.[1]
    const dir = dashC ? unquote(dashC) : cd ? unquote(cd) : undefined
    calls.push({ sub: match[2] ?? '', args: match[3] ?? '', ...(dir ? { dir } : {}) })
  }

  return calls
}

// Splits text into words, honouring quotes. Good enough to read flags and paths.
export function tokenize(text: string): string[] {
  return [...text.matchAll(/"((?:[^"\\]|\\.)*)"|'([^']*)'|(\S+)/g)].map(m => m[1] ?? m[2] ?? m[3] ?? '')
}

// --- risks -------------------------------------------------------------------------------

export type Rule = 'force-push' | 'no-verify' | 'stash-drop' | 'discard' | 'rm' | 'migrate'

export type MigrationTool = 'django' | 'rails' | 'alembic' | 'prisma' | 'unknown'

export type Risk =
  | { rule: 'force-push' | 'no-verify' | 'stash-drop' | 'discard'; label: string; call: GitCall }
  | { rule: 'rm'; label: string; targets: string[]; dir?: string }
  | { rule: 'migrate'; label: string; tool: MigrationTool; dir?: string }

export function gitRisks(call: GitCall): Risk[] {
  const risks: Risk[] = []
  if (call.sub === 'push' && isForcePush(call.args)) {
    risks.push({ rule: 'force-push', label: 'git push --force', call })
  }
  if (skipsHooks(call)) {
    risks.push({ rule: 'no-verify', label: `git ${call.sub} --no-verify`, call })
  }
  const loses = alwaysLoses(call)
  if (loses) {
    risks.push({ rule: 'stash-drop', label: loses, call })
  }
  if (discardsWorktree(call)) {
    risks.push({ rule: 'discard', label: `git ${call.sub} ${call.args.trim()}`.trim().slice(0, 80), call })
  }

  return risks
}

// --- push -------------------------------------------------------------------------------

export const PROTECTED_BRANCHES = ['main', 'master']

export function isForcePush(args: string): boolean {
  return /(?:^|\s)(?:--force(?:-with-lease)?(?:=\S*)?|--force-if-includes|-[a-zA-Z]*f[a-zA-Z]*)(?=\s|$)/.test(args) ||
    /(?:^|\s)\+\S+/.test(args)
}

export type PushTarget = {
  remote: string
  source: string
  // The remote branch, or undefined when the push sends the current one.
  branch?: string
}

// The branches a push overwrites: one per refspec, or the current branch when it names none.
export function pushTargets(args: string): PushTarget[] {
  const words = tokenize(args).filter(word => !word.startsWith('-'))
  const remote = words[0] ?? 'origin'
  const specs = words.slice(1)
  if (specs.length === 0) {
    return [{ remote, source: 'HEAD' }]
  }

  return specs.map(spec => {
    // A refspec is src:dst; with no colon the local branch of the same name is pushed.
    const [source = '', target = source] = spec.replace(/^\+/, '').split(':')
    const branch = target.replace(/^refs\/heads\//, '')

    return branch === '' || branch === 'HEAD'
      ? { remote, source: 'HEAD' }
      : { remote, source: source === '' ? 'HEAD' : source, branch }
  })
}

// --- destructive local operations -----------------------------------------------------

// Operations that can throw away uncommitted work; register.tsx asks only when they would.
export function discardsWorktree(call: GitCall): string | undefined {
  const { sub, args } = call
  if (sub === 'reset' && /(?:^|\s)--hard\b/.test(args)) {
    return 'git reset --hard'
  }
  if (sub === 'checkout' && /(?:^|\s)(?:--\s|\.(?:\s|$))/.test(args)) {
    return 'git checkout -- <path>'
  }
  if (sub === 'restore' && (!/(?:^|\s)(?:--staged|-S)\b/.test(args) || /(?:^|\s)(?:--worktree|-W)\b/.test(args))) {
    return 'git restore <path>'
  }
  if (sub === 'clean' && /(?:^|\s)-[a-zA-Z]*f/.test(args)) {
    return 'git clean -f'
  }

  return undefined
}

export type DiscardScope = {
  // Pathspecs the command limits itself to; empty means the whole worktree.
  paths: string[]
  // Whether staged changes are lost too, not just unstaged ones.
  isStagedLost: boolean
}

// Which uncommitted changes a reset --hard, checkout or restore overwrites.
export function discardScope(call: GitCall): DiscardScope {
  const words = tokenize(call.args)
  if (call.sub === 'reset') {
    return { paths: [], isStagedLost: true }
  }
  if (call.sub === 'restore') {
    const paths: string[] = []
    for (let i = 0; i < words.length; i += 1) {
      const word = words[i] ?? ''
      if (word === '-s' || word === '--source') {
        i += 1
      } else if (word === '--') {
        paths.push(...words.slice(i + 1))
        break
      } else if (!word.startsWith('-')) {
        paths.push(word)
      }
    }
    const isStaged = words.some(word => word === '--staged' || /^-[a-zA-Z]*S/.test(word))

    return { paths, isStagedLost: isStaged }
  }
  // checkout [<tree-ish>] [--] <paths>: a tree-ish overwrites the index as well.
  const dashes = words.indexOf('--')
  const before = (dashes === -1 ? words : words.slice(0, dashes)).filter(word => !word.startsWith('-'))
  if (dashes !== -1) {
    return { paths: words.slice(dashes + 1), isStagedLost: before.length > 0 }
  }

  return before.length > 1 ? { paths: before.slice(1), isStagedLost: true } : { paths: before, isStagedLost: false }
}

// The flags and paths of a `git clean`, for the dry run that lists what it removes.
export function cleanDryRun(args: string): string[] {
  const words = tokenize(args)
  const flags: string[] = []
  const paths: string[] = []
  for (let i = 0; i < words.length; i += 1) {
    const word = words[i] ?? ''
    if (word === '--') {
      paths.push(...words.slice(i + 1))
      break
    }
    if (word === '-e' || word === '--exclude') {
      flags.push(word, words[i + 1] ?? '')
      i += 1
    } else if (word.startsWith('--exclude=') || /^-e./.test(word)) {
      flags.push(word)
    } else if (/^-[a-zA-Z]+$/.test(word)) {
      // -n is added by the caller; -f, -i and -q would change the dry run.
      const kept = word.replace(/[finq]/g, '')
      if (kept !== '-') {
        flags.push(kept)
      }
    } else if (!word.startsWith('-')) {
      paths.push(word)
    }
  }

  return ['clean', '-n', ...flags, '--', ...paths]
}

// Operations that lose work whatever the worktree looks like.
export function alwaysLoses(call: GitCall): string | undefined {
  if (call.sub === 'stash' && /^\s*(?:drop|clear)\b/.test(call.args)) {
    return `git stash ${call.args.trim().split(/\s+/)[0]}`
  }

  return undefined
}

// The stash a `git stash drop` names, or undefined for `clear` (all of them).
export function droppedStash(call: GitCall): string | undefined {
  const [verb, ref] = tokenize(call.args)

  return verb === 'drop' ? (ref ?? 'stash@{0}') : undefined
}

export function skipsHooks(call: GitCall): boolean {
  if (call.sub === 'commit') {
    return /(?:^|\s)(?:--no-verify|-n)(?=\s|$)/.test(call.args)
  }
  // `git push -n` is --dry-run, so only the long form counts there.
  return call.sub === 'push' && /(?:^|\s)--no-verify(?=\s|$)/.test(call.args)
}

// --- rm and migrations ------------------------------------------------------------------

// Heredoc bodies are data (a commit message that mentions rm -rf), not commands.
function stripHeredocs(command: string): string {
  return command.replace(/<<-?\s*(['"]?)(\w+)\1[^\n]*\n[\s\S]*?\n[ \t]*\2(?=[ \t]*(?:\n|$|\)))/g, match =>
    match.slice(0, match.indexOf('\n')),
  )
}

// Splits a command line at ; && || | & and newlines outside quotes.
export function segments(command: string): string[] {
  const text = stripHeredocs(command)
  const out: string[] = []
  let current = ''
  let quote: string | undefined
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i] ?? ''
    if (quote) {
      current += c
      if (c === '\\' && quote === '"') {
        current += text[(i += 1)] ?? ''
      } else if (c === quote) {
        quote = undefined
      }
      continue
    }
    if (c === '"' || c === "'") {
      quote = c
      current += c
    } else if (c === '\\') {
      current += c + (text[(i += 1)] ?? '')
    } else if (c === '&' && (text[i - 1] === '>' || text[i + 1] === '>')) {
      current += c // 2>&1, &> file
    } else if (c === ';' || c === '\n' || c === '|' || c === '&') {
      out.push(current)
      current = ''
      if ((c === '|' || c === '&') && text[i + 1] === c) {
        i += 1
      }
    } else {
      current += c
    }
  }
  out.push(current)

  return out.filter(segment => segment.trim() !== '')
}

// Words that can come before the real command without changing what it does.
const PREFIXES = new Set(['command', 'exec', 'env', 'nohup', 'time', 'then', 'do', 'else', '!'])
// sudo options that take a value, so the value isn't read as the command.
const SUDO_VALUE_OPTIONS = new Set(['-u', '-g', '-C', '-D', '-h', '-p', '-r', '-t', '-T', '-U'])
// Commands that only read, so a bare word "migrate" in them isn't a migration.
const READ_ONLY = new Set(['ls', 'cat', 'echo', 'printf', 'grep', 'rg', 'find', 'less', 'head', 'tail', 'cd', 'git'])

// The folder a later `cd arg` moves to, given the folder so far (undefined: the session's).
function joinDir(dir: string | undefined, arg: string | undefined): string {
  if (arg === undefined || arg === '~' || arg.startsWith('/') || arg.startsWith('~/')) {
    return arg ?? '~'
  }

  return dir ? `${dir}/${arg}` : arg
}

// The command's own words: leading VAR=value, sudo and harmless prefixes dropped.
function commandWords(segment: string): string[] {
  const words = tokenize(segment.trim().replace(/^[({]+\s*/, '').replace(/\s*[)}]+$/, ''))
  const isAssignment = (word: string) => /^[A-Za-z_][A-Za-z0-9_]*=/.test(word)
  while (words.length > 0 && isAssignment(words[0] ?? '')) {
    words.shift()
  }
  if (words[0] === 'sudo') {
    words.shift()
    while (words[0]?.startsWith('-')) {
      if (SUDO_VALUE_OPTIONS.has(words.shift() ?? '')) {
        words.shift()
      }
    }
  }
  while (words.length > 0 && (PREFIXES.has(words[0] ?? '') || isAssignment(words[0] ?? ''))) {
    words.shift()
  }
  if (words[0] === 'nice') {
    words.shift()
    const option = words.at(0) ?? ''
    if (option === '-n') {
      words.splice(0, 2)
    } else if (/^-\d+$/.test(option)) {
      words.shift()
    }
  }

  return words
}

function migration(cmd: string, args: string[], dir: string | undefined): Risk | undefined {
  const joined = [cmd, ...args].join(' ')
  const at = dir ? { dir } : {}
  if (/\bprisma\s+migrate\s+(?:status|diff)\b/.test(joined) || /\bdb:migrate:status\b/.test(joined)) {
    return undefined
  }
  if (/\balembic\s+upgrade\b/.test(joined)) {
    return { rule: 'migrate', label: 'alembic upgrade', tool: 'alembic', ...at }
  }
  if (/\bdb:migrate\b/.test(joined)) {
    return { rule: 'migrate', label: 'db:migrate', tool: 'rails', ...at }
  }
  if (/\bprisma\s+migrate\s+(?:dev|deploy)\b/.test(joined)) {
    return { rule: 'migrate', label: 'prisma migrate', tool: 'prisma', ...at }
  }
  if (/\bmanage\.py\s+migrate\b/.test(joined)) {
    return { rule: 'migrate', label: 'manage.py migrate', tool: 'django', ...at }
  }
  if (!READ_ONLY.has(cmd) && args.includes('migrate')) {
    return { rule: 'migrate', label: joined.slice(0, 60), tool: 'unknown', ...at }
  }

  return undefined
}

// The rm -r/-f calls and migrations in a command line, each with the folder it runs in as
// far as `cd`, `pushd` and `popd` earlier on the line move it.
export function shellRisks(command: string): Risk[] {
  const risks: Risk[] = []
  let dir: string | undefined
  const scopes: (string | undefined)[] = [] // dir to restore when a ( subshell ) closes
  const pushed: (string | undefined)[] = [] // pushd stack, for popd
  for (const raw of segments(command)) {
    const opens = /^\s*\(+/.exec(raw)?.[0].trim().length ?? 0
    // Trailing redirects and & don't hide a closing ) : `(cd sub && make) > log`.
    const tail = raw.replace(/(?:\s*(?:\d*>>?|&>>?|<)\s*\S+)+\s*$/, '')
    const closes = /\)+\s*$/.exec(tail)?.[0].trim().length ?? 0
    for (let k = 0; k < opens; k += 1) {
      scopes.push(dir)
    }

    const [first, ...args] = commandWords(raw)
    const cmd = (first ?? '').replace(/^\\/, '') // \rm skips aliases; it's still rm
    if (cmd === 'cd') {
      dir = args[0] === '-' ? '-' : joinDir(dir, args[0])
    } else if (cmd === 'pushd') {
      pushed.push(dir)
      dir = joinDir(dir, args[0])
    } else if (cmd === 'popd') {
      dir = pushed.length > 0 ? pushed.pop() : '-'
    } else if (cmd === 'rm' || cmd.endsWith('/rm')) {
      const dashes = args.indexOf('--')
      const options = (dashes === -1 ? args : args.slice(0, dashes)).filter(arg => arg.startsWith('-'))
      const isRecursive = options.some(flag => flag === '--recursive' || /^-[a-zA-Z]*[rR]/.test(flag))
      const isForced = options.some(flag => flag === '--force' || /^-[a-zA-Z]*f/.test(flag))
      if (isRecursive || isForced) {
        const targets = dashes === -1
          ? args.filter(arg => !arg.startsWith('-'))
          : [...args.slice(0, dashes).filter(arg => !arg.startsWith('-')), ...args.slice(dashes + 1)]
        risks.push({ rule: 'rm', label: `rm ${options.join(' ')}`, targets, ...(dir ? { dir } : {}) })
      }
    } else if (cmd !== '') {
      const risk = migration(cmd, args, dir)
      if (risk) {
        risks.push(risk)
      }
    }

    for (let k = 0; k < closes && scopes.length > 0; k += 1) {
      dir = scopes.pop() // a cd inside ( ... ) doesn't outlive it
    }
  }

  return risks
}

// --- commit messages ------------------------------------------------------------------

const ATTRIBUTION = [
  /^[ \t]*Co-Authored-By:[^\n]*(?:Claude|anthropic\.com)[^\n]*\n?/gim,
  /^[^\n]*Generated with \[?Claude Code[^\n]*\n?/gim,
]

// Removes Claude's co-author trailer and "Generated with Claude Code" line from a command.
export function stripAttribution(command: string): { command: string; isChanged: boolean } {
  let out = command
  for (const pattern of ATTRIBUTION) {
    out = out.replace(pattern, '')
  }
  // Lines removed at the end of a message leave blank lines before the closing quote or EOF.
  out = out.replace(/\n{2,}(\s*(?:EOF|["']))/g, '\n$1')

  return { command: out, isChanged: out !== command }
}

// The first line of the message a `git commit` gives inline, or undefined when it gives none
// this can read (an editor, -F, --no-edit, -C).
export function commitSubject(command: string, args: string): string | undefined {
  if (/(?:^|\s)(?:-F|--file|-C|-c|--reuse-message|--reedit-message|--no-edit|--fixup|--squash)\b/.test(args)) {
    return undefined
  }
  // Read from this commit on: a heredoc or a `-m` before it (a script, `python3 -m`) is not its message.
  const tail = commitTail(command, args)
  // `-m` may close a cluster of short flags (`-am`, `-qam`): the word after it is still the message.
  const heredoc = /(?:^|\s)(?:-[a-zA-Z]*m|--message)(?:=|\s+)["']?\$\(\s*cat\s+<<-?\s*['"]?(\w+)['"]?[^\n]*\n([\s\S]*?)\n\s*\1\b/.exec(tail)
  if (heredoc) {
    return firstLine(heredoc[2] ?? '')
  }
  const inline = /(?:^|\s)(?:-[a-zA-Z]*m|--message)(?:=|\s+)(?:"((?:[^"\\]|\\.)*)"|'([^']*)'|(\S+))/.exec(tail)
  if (!inline) {
    return undefined
  }

  return firstLine(inline[1] ?? inline[2] ?? inline[3] ?? '')
}

const COMMIT_CALL =
  /(?:^|[;&|(\n`]|\$\()\s*(?:[A-Z_][A-Z0-9_]*=\S*\s+)*git(?:\s+-[Cc]\s+(?:"[^"]*"|'[^']*'|\S+)|\s+--[a-z-]+(?:=\S+)?)*\s+commit/g

// The command line from the `git commit` whose args are `args` on, past the `;&|` that end `args`.
function commitTail(command: string, args: string): string {
  for (const match of command.matchAll(COMMIT_CALL)) {
    const rest = command.slice(match.index + match[0].length)
    if (rest.startsWith(args)) {
      return rest
    }
  }

  return args
}

function firstLine(text: string): string | undefined {
  return text.split('\n').map(line => line.trim()).find(line => line !== '')
}

// `<emoji> type(scope)!: description`, emoji and scope optional, as the commit skill writes them.
const CONVENTIONAL = /^(?:\S+\s+)?[a-z]+(?:\([^)]+\))?!?: \S/

const EXEMPT_SUBJECT = /^(?:Merge |Revert "|fixup! |squash! |amend! |Initial commit)/

// `pattern`: the setting `commit_pattern`, in place of Conventional Commits.
export function badSubject(subject: string, pattern: RegExp = CONVENTIONAL): boolean {
  return !EXEMPT_SUBJECT.test(subject) && !pattern.test(subject)
}

files.hooks/config.ts:
// Layered settings, shared by every mod: the same file sits in each mod's hooks folder (a mod
// cannot import outside its own folder), and scripts/check-copies.sh keeps the copies equal.
//
// Precedence, highest first: session (`/<mod> set --session`), `.claude/cc-mod-trimtab.local.json`,
// `.claude/cc-mod-trimtab.json` (committed, held to each key's repo rule), the user layer
// (`/config` for single values, `~/.claude/cc-mod-trimtab.json` for lists), the default.
// Every file holds `{ "<mod>": { "<key>": value } }`, and may hold a `"*"` section beside them: of
// that one only `language` is read, as the value every mod shares (a mod's own section wins).
//
// A feature that spends tokens is a key with a `toggle`: `/<mod> on [feature] [duration]` sets its
// session value until a time (2h by default), `/<mod> off [feature]` takes it back.

import type { PluginOptions } from 'claude-code'

export type Value = boolean | number | string | readonly string[]

// The language of everything shown on screen. Text for the model is English whatever this is.
export type Lang = 'en' | 'zh-TW'

export type Text = Readonly<Record<Lang, string>>

export function pick(lang: Lang, text: Text): string {
  return text[lang]
}

// A description is one string (tests) or a pair.
export function say(lang: Lang, text: string | Text): string {
  return typeof text === 'string' ? text : text[lang]
}

// Where the model writes for the person (memories, handoffs), the prompt names the language.
export function writeIn(lang: Lang): string {
  return lang === 'zh-TW' ? 'Write in Traditional Chinese (zh-TW).' : 'Write in English.'
}

export type Layer = 'default' | 'user' | 'repo' | 'local' | 'session'

// What the committed repo file may do: a clone must not loosen a protection or switch on spending.
// `append` adds to the list below it; `never` leaves the key to the person's own layers.
export type RepoRule = 'any' | 'only-true' | 'only-false' | 'only-lower' | 'only-higher' | 'append' | 'never'

export type Category = 'protect' | 'cost' | 'plain'

export type KeySpec = {
  category: Category
  type: 'boolean' | 'number' | 'string' | 'list'
  default: Value
  repo: RepoRule
  description: string | Text
  min?: number
  max?: number
  // The values a string may take.
  choices?: readonly string[]
  // A feature `/<mod> on|off` switches: the value each one sets.
  toggle?: { on: Value; off: Value }
}

export type Specs = Readonly<Record<string, KeySpec>>

// The key every mod has: the language of what it shows. One value may stand for all mods in a
// settings file's `"*"` section. It is the person's own taste, so the repo file cannot set it.
export const LANGUAGE: KeySpec = {
  category: 'plain',
  type: 'string',
  default: 'en',
  repo: 'never',
  choices: ['en', 'zh-TW'],
  description: {
    en: 'Language of what this mod shows: en or zh-TW. Put {"*": {"language": "..."}} in a settings file to set it for every mod.',
    'zh-TW': '這個 mod 顯示的語言：en 或 zh-TW。在設定檔放 {"*": {"language": "..."}} 可一次設定所有 mod。',
  },
}

export type Ignored = { key: string; layer: Layer; reason: string }

export type Resolved = {
  // The language the values come to (`language`, English without it).
  lang: Lang
  values: Readonly<Record<string, Value>>
  sources: Readonly<Record<string, Layer>>
  ignored: readonly Ignored[]
  // When each key switched on by `/<mod> on` goes back, for the keys whose value it decides.
  until: Readonly<Record<string, number>>
}

export type Target = 'session' | 'local' | 'repo'

type Raw = Readonly<Record<string, unknown>>

export type Layers = {
  options: PluginOptions
  user: Raw
  repo: Raw
  local: Raw
  session: Raw
  // When the session values set by `/<mod> on` run out; the expired ones are left out already.
  until?: Readonly<Record<string, number>>
}

export const REPO_FILE = '.claude/cc-mod-trimtab.json'
export const LOCAL_FILE = '.claude/cc-mod-trimtab.local.json'
const USER_FILE = 'cc-mod-trimtab.json'
// Both keyed by session id: `$.store` is one file every session of the mod shares.
const SESSION_KEY = 'config-sessions'
const NOTICED_KEY = 'config-noticed-sessions'
// The settings files' section for what every mod shares.
const SHARED = '*'

const DEFAULT_ON_MS = 2 * 3_600_000
const MAX_ON_MS = 24 * 3_600_000
// A session's entries are dropped once nothing wrote them for this long.
const KEEP_SESSION_MS = 7 * 86_400_000

const LAYER_NAMES: Readonly<Record<Layer, Text>> = {
  default: { en: 'default', 'zh-TW': '預設' },
  user: { en: 'user', 'zh-TW': '使用者' },
  repo: { en: 'repo', 'zh-TW': 'repo' },
  local: { en: 'local', 'zh-TW': 'local' },
  session: { en: 'session', 'zh-TW': 'session' },
}

const CATEGORY_NAMES: Readonly<Record<Category, Text>> = {
  protect: { en: 'protection', 'zh-TW': '保護' },
  cost: { en: 'cost', 'zh-TW': '花費' },
  plain: { en: 'general', 'zh-TW': '一般' },
}

const RULE_NAMES: Readonly<Record<RepoRule, Text>> = {
  any: { en: 'repo may set freely', 'zh-TW': 'repo 可自由設定' },
  'only-true': { en: 'repo may only turn on', 'zh-TW': 'repo 只能開啟' },
  'only-false': { en: 'repo may only turn off', 'zh-TW': 'repo 只能關閉' },
  'only-lower': { en: 'repo may only lower', 'zh-TW': 'repo 只能調低' },
  'only-higher': { en: 'repo may only raise', 'zh-TW': 'repo 只能調高' },
  append: { en: 'repo may only add items', 'zh-TW': 'repo 只能加項目' },
  never: { en: 'repo may not set', 'zh-TW': 'repo 不能設定' },
}

function langOf(value: unknown): Lang {
  return value === 'zh-TW' ? 'zh-TW' : 'en'
}

function listOf(lang: Lang, items: readonly string[]): string {
  return items.join(lang === 'zh-TW' ? '、' : ', ')
}

// ---------- pure ----------

// A stored value of the key's type, or why it is not one.
export function parseValue(spec: KeySpec, raw: unknown, lang: Lang = 'en'): { value: Value } | { error: string } {
  switch (spec.type) {
    case 'boolean':
      return typeof raw === 'boolean' ? { value: raw } : { error: pick(lang, { en: 'must be true or false', 'zh-TW': '要是 true 或 false' }) }
    case 'number': {
      if (typeof raw !== 'number' || !Number.isFinite(raw)) {
        return { error: pick(lang, { en: 'must be a number', 'zh-TW': '要是數字' }) }
      }
      if ((spec.min !== undefined && raw < spec.min) || (spec.max !== undefined && raw > spec.max)) {
        const min = spec.min ?? '-∞'
        const max = spec.max ?? '∞'

        return { error: pick(lang, { en: `must be between ${min} and ${max}`, 'zh-TW': `要在 ${min} 到 ${max} 之間` }) }
      }

      return { value: raw }
    }
    case 'string':
      if (typeof raw !== 'string') {
        return { error: pick(lang, { en: 'must be a string', 'zh-TW': '要是字串' }) }
      }
      if (spec.choices !== undefined && !spec.choices.includes(raw)) {
        return { error: pick(lang, { en: `must be one of ${listOf(lang, spec.choices)}`, 'zh-TW': `要是 ${listOf(lang, spec.choices)} 之一` }) }
      }

      return { value: raw }
    case 'list':
      return Array.isArray(raw) && raw.every(item => typeof item === 'string')
        ? { value: raw as readonly string[] }
        : { error: pick(lang, { en: 'must be an array of strings', 'zh-TW': '要是字串陣列' }) }
  }
}

// A value typed after `/<mod> set <key>`: on/off for booleans; for lists a JSON array, or the
// whole text as one item (commas are common in a pattern, so they do not split).
export function parseInput(spec: KeySpec, text: string, lang: Lang = 'en'): { value: Value } | { error: string } {
  const t = text.trim()
  switch (spec.type) {
    case 'boolean': {
      const on = ['true', 'on', 'yes', '1'].includes(t.toLowerCase())
      const off = ['false', 'off', 'no', '0'].includes(t.toLowerCase())

      return on || off ? { value: on } : { error: pick(lang, { en: 'must be on or off', 'zh-TW': '要是 on 或 off' }) }
    }
    case 'number':
      return parseValue(spec, t === '' ? Number.NaN : Number(t), lang)
    case 'string':
      return parseValue(spec, t, lang)
    case 'list': {
      if (t.startsWith('[')) {
        try {
          return parseValue(spec, JSON.parse(t), lang)
        } catch {
          return { error: pick(lang, { en: 'not a valid JSON array', 'zh-TW': 'JSON 陣列格式不對' }) }
        }
      }

      return { value: t === '' ? [] : [t] }
    }
  }
}

function same(a: Value, b: Value): boolean {
  return JSON.stringify(a) === JSON.stringify(b)
}

// What the repo file's value comes to over the one below it, or why it is ignored.
export function applyRepoRule(spec: KeySpec, below: Value, value: Value, lang: Lang = 'en'): { value: Value } | { error: string } {
  // `never` refuses even the value below it, so `set --repo` cannot write the key at all.
  if (spec.repo !== 'never' && (same(below, value) || spec.repo === 'any')) {
    return { value }
  }
  switch (spec.repo) {
    case 'only-true':
      return value === true ? { value } : { error: pick(lang, { en: 'protection key: the repo file may only turn it on', 'zh-TW': '保護類，repo 檔案只能開啟' }) }
    case 'only-false':
      return value === false ? { value } : { error: pick(lang, { en: 'cost key: the repo file may only turn it off', 'zh-TW': '花費類，repo 檔案只能關閉' }) }
    case 'only-lower':
      return (value as number) < (below as number) ? { value } : { error: pick(lang, { en: 'the repo file may only lower it', 'zh-TW': 'repo 檔案只能調低' }) }
    case 'only-higher':
      return (value as number) > (below as number) ? { value } : { error: pick(lang, { en: 'the repo file may only raise it', 'zh-TW': 'repo 檔案只能調高' }) }
    case 'append':
      return { value: [...new Set([...(below as readonly string[]), ...(value as readonly string[])])] }
    case 'never':
      return { error: pick(lang, { en: 'the repo file may not set it; use the local file', 'zh-TW': 'repo 檔案不能設定，改用 local 檔案' }) }
  }
}

// The one key whose user layer is the settings file, single value or not: `/config` cannot hold
// a value shared by every mod.
function isFileValue(key: string, spec: KeySpec): boolean {
  return spec.type === 'list' || key === 'language'
}

function resolveKey(key: string, spec: KeySpec, layers: Layers, lang: Lang, ignored: Ignored[]): { value: Value; source: Layer } {
  let value = spec.default
  let source: Layer = 'default'
  const take = (layer: Layer, raw: unknown) => {
    if (raw === undefined) {
      return
    }
    const parsed = parseValue(spec, raw, lang)
    if ('error' in parsed) {
      ignored.push({ key, layer, reason: parsed.error })

      return
    }
    const applied = layer === 'repo' ? applyRepoRule(spec, value, parsed.value, lang) : parsed
    if ('error' in applied) {
      ignored.push({ key, layer, reason: applied.error })

      return
    }
    if (layer === 'user' && same(applied.value, spec.default)) {
      // `/config` hands over defaults filled in: the same value is no choice of the person's.
      return
    }
    value = applied.value
    source = layer
  }
  // Lists have no `/config` row; their user layer is the file.
  take('user', isFileValue(key, spec) ? layers.user[key] : layers.options[key])
  take('repo', layers.repo[key])
  take('local', layers.local[key])
  take('session', layers.session[key])

  return { value, source }
}

export function resolve(specs: Specs, layers: Layers): Resolved {
  const values: Record<string, Value> = {}
  const sources: Record<string, Layer> = {}
  const ignored: Ignored[] = []
  // The language first: the other keys' reasons are worded in it.
  const languageSpec = Object.hasOwn(specs, 'language') ? (specs.language as KeySpec) : LANGUAGE
  const lang = langOf(resolveKey('language', languageSpec, layers, 'en', []).value)
  for (const [key, spec] of Object.entries(specs)) {
    const one = resolveKey(key, spec, layers, lang, ignored)
    values[key] = one.value
    sources[key] = one.source
  }
  for (const layer of ['user', 'repo', 'local', 'session'] as const) {
    for (const key of Object.keys(layers[layer])) {
      const spec = Object.hasOwn(specs, key) ? specs[key] : undefined
      if (spec === undefined) {
        ignored.push({ key, layer, reason: pick(lang, { en: 'no such setting', 'zh-TW': '沒有這個設定' }) })
      } else if (layer === 'user' && !isFileValue(key, spec)) {
        ignored.push({
          key,
          layer,
          reason: pick(lang, { en: 'the user settings file holds lists only; use /config for a single value', 'zh-TW': '使用者設定檔只放清單，單一值用 /config' }),
        })
      }
    }
  }

  const until: Record<string, number> = {}
  for (const [key, at] of Object.entries(layers.until ?? {})) {
    if (sources[key] === 'session' && Object.hasOwn(layers.session, key)) {
      until[key] = at
    }
  }

  return { lang, values, sources, ignored, until }
}

// `2h`, `90m`, `1h30m`, or a bare number of minutes.
export function parseDuration(text: string): number | undefined {
  const t = text.trim().toLowerCase()
  const match = /^(?:(\d+)h)?(?:(\d+)m?)?$/.exec(t)
  if (t === '' || match === null || (match[1] === undefined && match[2] === undefined)) {
    return undefined
  }
  const ms = Number(match[1] ?? 0) * 3_600_000 + Number(match[2] ?? 0) * 60_000

  return ms > 0 && ms <= MAX_ON_MS ? ms : undefined
}

// `1h42m`, `37m`, `<1m`.
export function fmtLeft(ms: number): string {
  const minutes = Math.ceil(ms / 60_000)
  if (ms < 60_000) {
    return '<1m'
  }
  const h = Math.floor(minutes / 60)
  const m = minutes % 60

  return h === 0 ? `${m}m` : m === 0 ? `${h}h` : `${h}h${m}m`
}

// The band line while a feature is on for a while: `<mod> on · keep_warm 1h42m`, '' when none is.
export function onLine(mod: string, until: Readonly<Record<string, number>>, now: number): string {
  const parts = Object.entries(until)
    .filter(([, at]) => at > now)
    .map(([key, at]) => `${key} ${fmtLeft(at - now)}`)

  return parts.length === 0 ? '' : [`${mod} on`, ...parts].join(' · ')
}

// When the first of the features switched on for a while goes back.
export function nextExpiry(resolved: Resolved): number | undefined {
  const times = Object.values(resolved.until)

  return times.length === 0 ? undefined : Math.min(...times)
}

function show(value: Value): string {
  return Array.isArray(value) ? (value.length === 0 ? '[]' : value.join(', ')) : String(value)
}

export function statusText(mod: string, specs: Specs, resolved: Resolved, now = 0): string {
  const lang = resolved.lang
  const keys = Object.keys(specs)
  if (keys.length === 0) {
    return pick(lang, { en: `${mod} has no settings.`, 'zh-TW': `${mod} 沒有可調的設定。` })
  }
  const lines = [
    pick(lang, {
      en: `${mod} settings (precedence: session > local > repo > user > default)`,
      'zh-TW': `${mod} 設定（優先：session > local > repo > 使用者 > 預設）`,
    }),
  ]
  for (const key of keys) {
    const spec = specs[key] as KeySpec
    const value = resolved.values[key] as Value
    const source = resolved.sources[key] as Layer
    const at = resolved.until[key]
    const left = at === undefined ? '' : pick(lang, { en: `, on temporarily for ${fmtLeft(at - now)}`, 'zh-TW': `，臨時開啟剩 ${fmtLeft(at - now)}` })
    const kind = pick(lang, CATEGORY_NAMES[spec.category])
    const rule = pick(lang, RULE_NAMES[spec.repo])
    lines.push(`  ${key} = ${show(value)}  [${pick(lang, LAYER_NAMES[source])}${left}]  ${kind}${lang === 'zh-TW' ? '，' : ', '}${rule}`)
    lines.push(`    ${say(lang, spec.description)}`)
  }
  if (resolved.ignored.length > 0) {
    lines.push(pick(lang, { en: 'Ignored:', 'zh-TW': '已忽略：' }))
    for (const item of resolved.ignored) {
      const layer = pick(lang, LAYER_NAMES[item.layer])
      lines.push(pick(lang, { en: `  ${item.key} in ${layer}: ${item.reason}`, 'zh-TW': `  ${layer} 的 ${item.key}：${item.reason}` }))
    }
  }
  lines.push(
    pick(lang, {
      en: `Change: /${mod} set <key> <value> [--session|--local|--repo] (default --session); revert: /${mod} unset <key> [same flags]`,
      'zh-TW': `改值：/${mod} set <key> <value> [--session|--local|--repo]（預設 --session），還原：/${mod} unset <key> [同上]`,
    }),
  )
  const toggles = toggleKeys(specs)
  if (toggles.length > 0) {
    const names = listOf(lang, toggles)
    const feature = toggles.length === 1 ? '' : pick(lang, { en: ' <feature>', 'zh-TW': ' <功能>' })
    lines.push(
      pick(lang, {
        en: `Features that use the model (${names}): /${mod} on${feature} [duration, default 2h] turns one on for a while, /${mod} off${feature} turns it off`,
        'zh-TW': `用模型的功能（${names}）：/${mod} on${feature} [時長，預設 2h] 臨時開啟，/${mod} off${feature} 關閉`,
      }),
    )
  }

  return lines.join('\n')
}

function modSection(text: string, mod: string): Raw {
  if (text.trim() === '') {
    return {}
  }
  const parsed: unknown = JSON.parse(text)
  const section = typeof parsed === 'object' && parsed !== null ? (parsed as Raw)[mod] : undefined

  return typeof section === 'object' && section !== null && !Array.isArray(section) ? (section as Raw) : {}
}

// The file's text with the key set (or removed when `value` is undefined), other mods kept.
export function withSetting(text: string, mod: string, key: string, value: Value | undefined): string {
  const parsed: unknown = text.trim() === '' ? {} : JSON.parse(text)
  const all = typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed) ? { ...(parsed as Raw) } : {}
  const section = { ...modSection(text, mod) }
  if (value === undefined) {
    delete section[key]
  } else {
    section[key] = value
  }
  if (Object.keys(section).length === 0) {
    delete all[mod]
  } else {
    all[mod] = section
  }

  return `${JSON.stringify(all, null, 2)}\n`
}

export function withLocalExclude(text: string): string | undefined {
  const line = `/${LOCAL_FILE}`
  if (text.split('\n').some(l => l.trim() === line)) {
    return undefined
  }

  return `${text}${text === '' || text.endsWith('\n') ? '' : '\n'}# cc-mod-trimtab\n${line}\n`
}

const TARGET_FLAG = /(^|\s)--(session|local|repo)(?=\s|$)/g

// `<key> [value] [--session|--local|--repo]`, the flag anywhere. The value keeps its spacing.
export function parseSetArgs(args: string, lang: Lang = 'en'): { key: string; rest: string; target: Target } | { error: string } {
  const targets = [...args.matchAll(TARGET_FLAG)].map(match => match[2] as Target)
  if (targets.length > 1) {
    return { error: pick(lang, { en: 'give only one of --session, --local or --repo', 'zh-TW': '只能加一個 --session、--local 或 --repo' }) }
  }
  const text = args.replace(TARGET_FLAG, '$1').trim()
  const key = text.split(/\s+/)[0] ?? ''
  if (key === '') {
    return { error: pick(lang, { en: 'name a setting', 'zh-TW': '要指定設定名稱' }) }
  }

  return { key, rest: text.slice(key.length).trim(), target: targets[0] ?? 'session' }
}

// ---------- through the mod's I/O ----------

// What the settings need from `$`. `$` cannot cross an import, so each mod builds this in its own
// register file (the `configIO` block, kept equal across mods by scripts/check-copies.sh).
export type ConfigIO = {
  // The file's text, '' when it is missing.
  read: (path: string) => Promise<string>
  write: (path: string, text: string) => Promise<void>
  isDir: (path: string) => Promise<boolean>
  // `CLAUDE_CONFIG_DIR`, else `$HOME/.claude`.
  configDir: () => Promise<string>
  root: () => Promise<string>
  // The main working tree, whose `.git/info/exclude` covers every worktree.
  repoRoot: () => Promise<string | undefined>
  sessionId: () => Promise<string>
  now: () => Promise<number>
  storeGet: (key: string) => Promise<unknown>
  storeSet: (key: string, value: unknown) => Promise<void>
}

// What a file adds to the layers: the mod's section, with `language` from `"*"` when the section
// has none of its own, and the problems found on the way.
type Problem = { key: string; layer: Layer; reason: Text }

function readSection(text: string, path: string, mod: string, layer: Layer, broken: Problem[]): Raw {
  try {
    const own = modSection(text, mod)
    const shared = modSection(text, SHARED)
    for (const key of Object.keys(shared)) {
      if (key !== 'language') {
        broken.push({
          key: `${SHARED}.${key}`,
          layer,
          reason: { en: `only language is read from "${SHARED}"`, 'zh-TW': `"${SHARED}" 只讀 language` },
        })
      }
    }

    return shared.language === undefined || own.language !== undefined ? own : { ...own, language: shared.language }
  } catch {
    broken.push({ key: path, layer, reason: { en: 'not valid JSON; the whole file is not used', 'zh-TW': 'JSON 格式不對，整個檔案沒有採用' } })

    return {}
  }
}

type SessionEntry = { values: Raw; until?: Readonly<Record<string, number>> }
type Sessions<T> = Readonly<Record<string, T & { written: number }>>

// Every session's entry under `key`, with `id`'s replaced by `entry` and those not written for a
// week dropped.
async function writeSessions<T>(io: ConfigIO, key: string, id: string, entry: T): Promise<void> {
  const now = await io.now()
  const kept: Record<string, T & { written: number }> = {}
  for (const [other, stored] of Object.entries(((await io.storeGet(key)) ?? {}) as Sessions<T>)) {
    if (other !== id && now - stored.written < KEEP_SESSION_MS) {
      kept[other] = stored
    }
  }
  kept[id] = { ...entry, written: now }
  await io.storeSet(key, kept)
}

async function sessionEntry<T>(io: ConfigIO, key: string, id: string): Promise<T | undefined> {
  const stored = (await io.storeGet(key)) as Sessions<T> | undefined

  return stored !== undefined && Object.hasOwn(stored, id) ? stored[id] : undefined
}

// This session's values; those `/<mod> on` set left out once they ran out.
async function sessionValues(io: ConfigIO): Promise<{ values: Raw; until: Record<string, number> }> {
  const stored = await sessionEntry<SessionEntry>(io, SESSION_KEY, await io.sessionId())
  if (stored === undefined) {
    return { values: {}, until: {} }
  }
  const timed = Object.entries(stored.until ?? {})
  // Read only when needed: a mod without features to switch never asks the clock.
  const now = timed.length === 0 ? 0 : await io.now()
  const values: Record<string, unknown> = { ...stored.values }
  const until: Record<string, number> = {}
  for (const [key, at] of timed) {
    if (at > now) {
      until[key] = at
    } else {
      delete values[key]
    }
  }

  return { values, until }
}

async function writeSession(io: ConfigIO, key: string, value: Value | undefined, until: number | undefined): Promise<void> {
  const current = await sessionValues(io)
  const values: Record<string, unknown> = { ...current.values }
  const times = { ...current.until }
  delete values[key]
  delete times[key]
  if (value !== undefined) {
    values[key] = value
  }
  if (value !== undefined && until !== undefined) {
    times[key] = until
  }
  await writeSessions(io, SESSION_KEY, await io.sessionId(), { values, until: times })
}

// True the first time a feature does its work in this session, for the one notice it gets.
export async function firstUse(io: ConfigIO, key: string): Promise<boolean> {
  const sessionId = await io.sessionId()
  const keys = (await sessionEntry<{ keys: string[] }>(io, NOTICED_KEY, sessionId))?.keys ?? []
  if (keys.includes(key)) {
    return false
  }
  await writeSessions(io, NOTICED_KEY, sessionId, { keys: [...keys, key] })

  return true
}

async function filePaths(io: ConfigIO): Promise<{ user: string; repo: string; local: string }> {
  const root = (await io.root()).replace(/\/$/, '')

  return { user: `${(await io.configDir()).replace(/\/$/, '')}/${USER_FILE}`, repo: `${root}/${REPO_FILE}`, local: `${root}/${LOCAL_FILE}` }
}

async function loadLayers(io: ConfigIO, mod: string, options: PluginOptions): Promise<{ layers: Layers; broken: Problem[] }> {
  const paths = await filePaths(io)
  const broken: Problem[] = []
  const session = await sessionValues(io)
  const layers = {
    options,
    user: readSection(await io.read(paths.user), paths.user, mod, 'user', broken),
    repo: readSection(await io.read(paths.repo), paths.repo, mod, 'repo', broken),
    local: readSection(await io.read(paths.local), paths.local, mod, 'local', broken),
    session: session.values,
    until: session.until,
  }

  return { layers, broken }
}

export async function loadConfig(io: ConfigIO, mod: string, specs: Specs, options: PluginOptions): Promise<Resolved> {
  const { layers, broken } = await loadLayers(io, mod, options)
  const resolved = resolve(specs, layers)

  const problems = broken.map(item => ({ ...item, reason: pick(resolved.lang, item.reason) }))

  return { ...resolved, ignored: [...problems, ...resolved.ignored] }
}

async function writeSetting(io: ConfigIO, mod: string, key: string, value: Value | undefined, target: Target): Promise<void> {
  if (target === 'session') {
    await writeSession(io, key, value, undefined)

    return
  }
  const paths = await filePaths(io)
  const path = target === 'repo' ? paths.repo : paths.local
  await io.write(path, withSetting(await io.read(path), mod, key, value))
  if (target === 'local') {
    const repo = await io.repoRoot()
    if (repo !== undefined && (await io.isDir(`${repo}/.git`))) {
      const exclude = `${repo}/.git/info/exclude`
      const added = withLocalExclude(await io.read(exclude))
      if (added !== undefined) {
        await io.write(exclude, added)
      }
    }
  }
}

// Answers `/<mod> status|set|unset …`; undefined for any other sub-command. `reload` hands the
// mod the new values after a change.
export async function configCommand(
  io: ConfigIO,
  mod: string,
  specs: Specs,
  options: PluginOptions,
  args: string,
  reload: (resolved: Resolved) => void,
): Promise<string | undefined> {
  const sub = args.trim().split(/\s+/)[0] ?? ''
  const rest = args.trim().slice(sub.length)
  if (sub === 'status') {
    const resolved = await loadConfig(io, mod, specs, options)
    reload(resolved)

    return statusText(mod, specs, resolved, Object.keys(resolved.until).length === 0 ? 0 : await io.now())
  }
  if ((sub === 'on' || sub === 'off') && toggleKeys(specs).length > 0) {
    return switchFeature(io, mod, specs, options, sub, rest, reload)
  }
  if (sub !== 'set' && sub !== 'unset') {
    return undefined
  }
  const before = await loadLayers(io, mod, options)
  const lang = resolve(specs, before.layers).lang
  const parsed = parseSetArgs(rest, lang)
  if ('error' in parsed) {
    return parsed.error
  }
  const spec = Object.hasOwn(specs, parsed.key) ? specs[parsed.key] : undefined
  if (spec === undefined) {
    return pick(lang, {
      en: `${mod} has no setting ${parsed.key}; /${mod} status lists them all`,
      'zh-TW': `${mod} 沒有 ${parsed.key} 這個設定；/${mod} status 列出全部`,
    })
  }
  let value: Value | undefined
  if (sub === 'set') {
    const input = parseInput(spec, parsed.rest, lang)
    if ('error' in input) {
      return `${parsed.key} ${input.error}`
    }
    value = input.value
  }
  if (parsed.target === 'repo' && value !== undefined) {
    // Do not commit a value every reader would ignore.
    const { layers } = before
    const trial = resolve(specs, { ...layers, repo: { ...layers.repo, [parsed.key]: value } })
    const refused = trial.ignored.find(item => item.layer === 'repo' && item.key === parsed.key)
    if (refused !== undefined) {
      return pick(lang, { en: `Not written: ${refused.reason}`, 'zh-TW': `沒有寫入：${refused.reason}` })
    }
  }
  await writeSetting(io, mod, parsed.key, value, parsed.target)
  const resolved = await loadConfig(io, mod, specs, options)
  reload(resolved)
  const shown = show(resolved.values[parsed.key] as Value)
  const from = pick(resolved.lang, LAYER_NAMES[resolved.sources[parsed.key] as Layer])
  const now = pick(resolved.lang, { en: `${parsed.key} is now ${shown} (from ${from})`, 'zh-TW': `${parsed.key} 現在是 ${shown}（來自 ${from}）` })
  const where =
    parsed.target === 'session' ? pick(resolved.lang, { en: 'this session only', 'zh-TW': '只在這個 session' }) : parsed.target === 'repo' ? REPO_FILE : LOCAL_FILE
  const done = sub === 'set' ? pick(resolved.lang, { en: 'Set', 'zh-TW': '已設定' }) : pick(resolved.lang, { en: 'Removed', 'zh-TW': '已移除' })

  return pick(resolved.lang, { en: `${done} (${where}). ${now}`, 'zh-TW': `${done}（${where}）。${now}` })
}

export function toggleKeys(specs: Specs): string[] {
  return Object.keys(specs).filter(key => specs[key]?.toggle !== undefined)
}

// `[feature] [duration]` in either order; the feature may go when the mod has one.
export function parseOnArgs(specs: Specs, args: string, withDuration: boolean, lang: Lang = 'en'): { key: string; ms: number } | { error: string } {
  const toggles = toggleKeys(specs)
  let key: string | undefined
  let ms: number | undefined
  for (const word of args.trim().split(/\s+/).filter(w => w !== '')) {
    if (key === undefined && toggles.includes(word)) {
      key = word
      continue
    }
    const duration = withDuration && ms === undefined ? parseDuration(word) : undefined
    if (duration === undefined) {
      const names = listOf(lang, toggles)
      const hint = withDuration ? pick(lang, { en: '; a duration looks like 2h, 90m, 1h30m (24h at most)', 'zh-TW': '，時長像 2h、90m、1h30m（最多 24h）' }) : ''

      return { error: pick(lang, { en: `Cannot read "${word}": the features are ${names}${hint}`, 'zh-TW': `看不懂「${word}」：功能是 ${names}${hint}` }) }
    }
    ms = duration
  }
  if (key === undefined && toggles.length === 1) {
    key = toggles[0]
  }
  if (key === undefined) {
    return { error: pick(lang, { en: `Name a feature: ${listOf(lang, toggles)}`, 'zh-TW': `要指定功能：${listOf(lang, toggles)}` }) }
  }

  return { key, ms: ms ?? DEFAULT_ON_MS }
}

async function switchFeature(
  io: ConfigIO,
  mod: string,
  specs: Specs,
  options: PluginOptions,
  sub: 'on' | 'off',
  args: string,
  reload: (resolved: Resolved) => void,
): Promise<string> {
  const { layers } = await loadLayers(io, mod, options)
  const lang = resolve(specs, layers).lang
  const parsed = parseOnArgs(specs, args, sub === 'on', lang)
  if ('error' in parsed) {
    return parsed.error
  }
  const { key, ms } = parsed
  const toggle = (specs[key] as KeySpec).toggle as { on: Value; off: Value }
  const rest: Record<string, unknown> = { ...layers.session }
  delete rest[key]
  const below = resolve(specs, { ...layers, session: rest })
  const belowValue = below.values[key] as Value
  const isOnBelow = !same(belowValue, toggle.off)
  const now = await io.now()
  const from = pick(lang, LAYER_NAMES[below.sources[key] as Layer])
  if (sub === 'on') {
    if (isOnBelow) {
      const wasOff = Object.hasOwn(layers.session, key)
      await writeSession(io, key, undefined, undefined)
      reload(await loadConfig(io, mod, specs, options))
      const source = pick(lang, { en: `${show(belowValue)}, from ${from}`, 'zh-TW': `${show(belowValue)}，來自 ${from}` })

      return wasOff
        ? pick(lang, { en: `${key}: this session's off is cancelled, back to always on (${source})`, 'zh-TW': `${key} 取消這個 session 的關閉，回到常開（${source}）` })
        : pick(lang, { en: `${key} is already always on (${source}); no need to turn it on for a while`, 'zh-TW': `${key} 已經常開（${source}），不用臨時開啟` })
    }
    await writeSession(io, key, toggle.on, now + ms)
    reload(await loadConfig(io, mod, specs, options))
    const at = new Date(now + ms)
    const clock = `${String(at.getHours()).padStart(2, '0')}:${String(at.getMinutes()).padStart(2, '0')}`
    const off = `/${mod} off${toggleKeys(specs).length === 1 ? '' : ` ${key}`}`

    return pick(lang, {
      en: `${key} on for ${fmtLeft(ms)} (until ${clock}); it goes off by itself when that runs out or the session ends; turn off: ${off}`,
      'zh-TW': `${key} 臨時開啟 ${fmtLeft(ms)}（到 ${clock}），到期或 session 結束自動關；關閉：${off}`,
    })
  }
  // Off for the rest of the session; nothing to keep when the layers below are off already.
  await writeSession(io, key, isOnBelow ? toggle.off : undefined, undefined)
  reload(await loadConfig(io, mod, specs, options))

  return isOnBelow
    ? pick(lang, {
        en: `${key} is off for this session (${from} has it on; it comes back next session)`,
        'zh-TW': `${key} 在這個 session 關閉（${from} 設定是開啟，下個 session 恢復）`,
      })
    : pick(lang, { en: `${key} is already off`, 'zh-TW': `${key} 已關閉` })
}

